query RecruitingSlots($applicationId: String!, $planKey: String, $from: String, $away: String, $holidays: String, $weeks: String, $interviewers: String) {
    recruitingSlots(applicationId: $applicationId, planKey: $planKey, from: $from, away: $away, holidays: $holidays, weeks: $weeks, interviewers: $interviewers)
  }
